import { defaultVlans } from '../../model/network';
import type { Device, Kind, Network } from '../../model/networkTypes';

// Regression fixture for legacy project migration, separate from the selectable demo projects.
const device = (
  id: string,
  kind: Kind,
  name: string,
  ip: string,
  vlan: number,
  x: number,
  y: number,
): Device => ({
  id,
  kind,
  name,
  ip,
  ipMode: kind === 'workstation' || kind === 'accesspoint' ? 'auto' : 'static',
  vlan,
  x,
  y,
  online: true,
  rules: [],
});

